ALTER TABLE produits ADD (stock NUMBER DEFAULT 0);
UPDATE produits SET stock = 100;
CREATE TABLE journal (
  id NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  table_nom VARCHAR2(30), operation VARCHAR2(10), ligne_id NUMBER,
  utilisateur VARCHAR2(50), date_op DATE DEFAULT SYSDATE, details VARCHAR2(200));
- ALTER TABLE ... ADD pour la colonne ; UPDATE sans WHERE pour tous les produits ; IDENTITY pour l'automatisme (Oracle 12c+).

DECLARE
  v_nom  produits.nom%TYPE;
  v_prix produits.prix%TYPE;
BEGIN
  SELECT nom, prix INTO v_nom, v_prix FROM produits WHERE id = 3;
  DBMS_OUTPUT.PUT_LINE(v_nom || ' : ' || v_prix);
EXCEPTION
  WHEN NO_DATA_FOUND THEN DBMS_OUTPUT.PUT_LINE('Produit introuvable');
END;
/
- Pour 99999 sans EXCEPTION : ORA-01403 : no data found.
- La section EXCEPTION intercepte NO_DATA_FOUND.

