CREATE OR REPLACE FUNCTION fn_prix_ttc (p_prix IN NUMBER) RETURN NUMBER IS
BEGIN
  RETURN ROUND(p_prix * 1.18);
END;
/
SELECT id, nom, prix, fn_prix_ttc(prix) AS prix_ttc FROM produits;

CREATE OR REPLACE FUNCTION fn_total_client (p_client_id IN NUMBER) RETURN NUMBER IS
  v_total NUMBER;
BEGIN
  SELECT NVL(SUM(montant), 0) INTO v_total FROM commandes WHERE client_id = p_client_id;
  RETURN v_total;
END;
/
- Sans NVL, SUM sur zéro ligne renvoie NULL : la fonction retournerait NULL au lieu de 0.

CREATE OR REPLACE FUNCTION fn_statut_client (p_client_id IN NUMBER) RETURN VARCHAR2 IS
  v_total NUMBER := fn_total_client(p_client_id);
BEGIN
  IF    v_total >= 150000 THEN RETURN 'VIP';
  ELSIF v_total >=  50000 THEN RETURN 'Regulier';
  ELSE                         RETURN 'Occasionnel';
  END IF;
END;
/
SELECT id, nom FROM clients WHERE fn_statut_client(id) = 'VIP';
- Les seuils se testent du plus grand au plus petit.
- La fonction s'utilise comme une expression dans le WHERE.

CREATE OR REPLACE PROCEDURE sp_ajouter_client (p_nom IN VARCHAR2, p_email IN VARCHAR2, p_id OUT NUMBER) IS
BEGIN
  SELECT NVL(MAX(id), 0) + 1 INTO p_id FROM clients;
  INSERT INTO clients (id, nom, email, date_inscription) VALUES (p_id, p_nom, p_email, TRUNC(SYSDATE));
END;
/
- TRUNC(SYSDATE) supprime l'heure ; p_id OUT renvoie l'identifiant à l'appelant.
- Pas de COMMIT : c'est l'appelant qui valide ou annule la transaction (la procédure peut faire partie d'un enchaînement).

CREATE OR REPLACE PROCEDURE sp_recalculer_montant (p_commande_id IN NUMBER) IS
BEGIN
  UPDATE commandes
  SET montant = (SELECT NVL(SUM(p.prix * cp.quantite), 0)
                 FROM commande_produits cp JOIN produits p ON p.id = cp.produit_id
                 WHERE cp.commande_id = p_commande_id)
  WHERE id = p_commande_id;
  IF SQL%ROWCOUNT = 0 THEN
    RAISE_APPLICATION_ERROR(-20021, 'Commande inconnue');
  END IF;
END;
/
- Sous-requête dans le SET ; NVL pour le cas sans ligne ; SQL%ROWCOUNT = 0 pour la commande inconnue.

CREATE OR REPLACE TRIGGER trg_clients_journal
AFTER INSERT OR UPDATE OR DELETE ON clients
FOR EACH ROW
DECLARE
  v_op journal.operation%TYPE;
  v_id clients.id%TYPE;
BEGIN
  IF INSERTING THEN v_op := 'INSERT'; v_id := :NEW.id;
  ELSIF UPDATING THEN v_op := 'UPDATE'; v_id := :NEW.id;
  ELSE v_op := 'DELETE'; v_id := :OLD.id;
  END IF;
  INSERT INTO journal (table_nom, operation, ligne_id, utilisateur) VALUES ('CLIENTS', v_op, v_id, USER);
END;
/
- INSERTING/UPDATING/DELETING identifient l'opération ; à la suppression, :NEW est vide : utiliser :OLD.id.
- AFTER : la trace se fait une fois la modification effectuée.

CREATE OR REPLACE TRIGGER trg_produits_prix
BEFORE INSERT OR UPDATE OF prix ON produits
FOR EACH ROW
BEGIN
  IF :NEW.prix IS NULL OR :NEW.prix <= 0 THEN
    RAISE_APPLICATION_ERROR(-20030, 'Le prix doit etre strictement positif');
  END IF;
END;
/
- UPDATE OF prix : le trigger ne se déclenche que si la colonne prix figure dans la clause SET ; modifier seulement stock ne le déclenche pas.

CREATE OR REPLACE TRIGGER trg_lignes_stock
BEFORE INSERT ON commande_produits
FOR EACH ROW
DECLARE
  v_stock produits.stock%TYPE;
BEGIN
  SELECT stock INTO v_stock FROM produits WHERE id = :NEW.produit_id;
  IF v_stock < :NEW.quantite THEN
    RAISE_APPLICATION_ERROR(-20031, 'Stock insuffisant');
  ELSE
    UPDATE produits SET stock = stock - :NEW.quantite WHERE id = :NEW.produit_id;
  END IF;
END;
/
- BEFORE : on refuse avant l'écriture. La table lue et modifiée (produits) n'est pas la table du trigger : pas de mutation.
- L'UPDATE du stock ne déclenche pas trg_produits_prix (colonne prix non modifiée).
